mapper.select:
select frule.yield 
from FIN_CASH_CALC_RULE frule, FIN_CASH_INFO info
where info.cash_id = frule.cash_id
and info.finprod_id = #{finprodId, jdbcType = VARCHAR}   
and info.CASH_TYPE_1 = #{cashType1, jdbcType = VARCHAR}
and info.CASH_TYPE_2 = #{cashType2, jdbcType = VARCHAR}
and frule.eff_date = 
(
    select max(frule2.eff_date)
    from FIN_CASH_CALC_RULE frule2
    where frule2.cash_id = info.cash_id
    and DATE_FORMAT(frule2.eff_date, '%Y%m%d') <= #{cdate, jdbcType = VARCHAR}
)
